import { expect, Page } from '@playwright/test';
import { pp } from '../pricebook/pricebook-helpers';
import { addressInput, setEnglish, typeAndPickSuggestion } from './address-helpers';

export { ROLE } from '../pricebook/pricebook-helpers';
export { addressInput, typeAndPickSuggestion };

/** Лид в TTP Test Locks для Edit Lead (предусловие, не удалять). */
export const EDIT_LEAD_NAME = 'QA-App Lead';

export const city = (page: Page) => page.getByLabel('City', { exact: true });
export const region = (page: Page) => page.getByLabel('Region/State', { exact: true });
export const zip = (page: Page) => page.getByLabel('ZIP Code', { exact: true });

/** New Lead прямым адресом (Create new → New Lead ведёт на /CreateLead). */
export async function openNewLead(page: Page) {
  await setEnglish(page);
  await page.goto(pp('/CreateLead'));
  await expect(page.getByRole('heading', { name: 'New Lead' })).toBeVisible({ timeout: 30_000 });
  await expect(addressInput(page)).toBeVisible();
}

/** Leads → поиск → клик по строке лида → Edit Lead. */
export async function openEditLead(page: Page, name: string) {
  await setEnglish(page);
  await page.goto(pp('/Leads'));
  await page.getByPlaceholder('Search leads...').fill(name);
  await page.getByText(name, { exact: true }).filter({ visible: true }).first().click();
  await page.waitForURL(/\/EditLead\?id=/);
  await expect(page.getByRole('heading', { name: 'Edit Lead' })).toBeVisible();
  await expect(addressInput(page)).toBeVisible();
}

/** Очистить Address (поле может быть заполнено) перед вводом. */
export async function clearAddress(page: Page) {
  await addressInput(page).fill('');
  await expect(addressInput(page)).toHaveValue('');
}
